#!/usr/bin/env python3
"""Build SmallC corpus artifacts and C++ execution fixtures with the ISA assembler."""
import hashlib
import json
import subprocess
import sys
from pathlib import Path
from isa import assemble, decode, ROOT
from smallc import compile_source
from encoding import payload_text
from generate_kernel_fixtures import image_symbols

KINDS={'body':0,'address':1,'guard':2,'spill':3,'reload':4,'prologue':5,'epilogue':6,'call':7}
def digest(data):return hashlib.sha256(data).hexdigest()
def instructions(assembly,origin):
    result=[]
    for pc,code,text in assemble(assembly,origin):
        entry,values=decode(code);row=dict(pc=pc,bytes=len(code),text=text,family=entry['semantic'],identifier=entry['id'],kind='body',bank_move=entry['id'] in ('mov_b0_b1','mov_b1_b0'),address_alu=False)
        if entry['id'].startswith('mov_b1_') and entry.get('address',{}).get('base')=='B1':row.update(addressing='b1',displacement=0)
        for op in entry['operands']+entry.get('bit_operands',[]):
            if op['name'] in ('displacement','offset'):
                row['displacement']=values[op['name']];row['addressing']='sp' if entry['id'].startswith('mov_sp') else 'b1' if 'b1_' in entry['id'] else 'other'
            if entry['semantic'].startswith('branch_'):row['branch_distance']=values['displacement']
        result.append(row)
    return result

def generate(destination):
    directory=ROOT/'examples/workloads';out=Path(destination);out.parent.mkdir(parents=True,exist_ok=True)
    corpus=json.loads((directory/'corpus.json').read_text());artifacts=[]
    for spec in corpus['cases']:
        artifact=compile_source((directory/spec['source']).read_text());artifact.update(spec,variant='compiled')
        if 'helper' in spec:
            artifact['helper_artifact']=compile_source((directory/spec['helper']).read_text(),0xb000,True)
            assert artifact['helper_artifact']['entrypoints']['kernel_helper']==0xb000
        artifacts.append(artifact)
        if 'reference' in spec:
            ref=dict(artifact);ref.update(name=spec['name']+'_hand',variant='hand',comparison=spec['name'],assembly=(directory/spec['reference']).read_text(),frames={})
            rows=assemble(ref['assembly'],0x100);ref['entrypoints']={name:pc for name,pc in image_symbols(ref['assembly'],rows,0x100).items() if name.startswith('hand_')};ref['source']=spec['reference'];ref['source_sha256']=digest(ref['assembly'].encode());ref['code']=list(b''.join(b for _,b,_ in rows));ref['instructions']=instructions(ref['assembly'],0x100);artifacts.append(ref)
    boot=(ROOT/'examples/kernel_console_boot.asm').read_text().replace('MOV.W #$0200,r0\nMOV.W r0,[r4+12]','MOV.W #$4000,r0\nMOV.W r0,[r4+12]')
    assert boot.count('MOV.W #$4000,r0')==2
    kernel=(ROOT/'examples/kernel_console.asm').read_text().replace('CMPI.W #$0200,r0\nBCS invalid_candidate','CMPI.W #$4000,r0\nBCS invalid_candidate')
    kernel=kernel.replace('MOV.W [r5+32],r0\nCMPI.W #3,r0\nBNE invalid_candidate','MOV.W [r5+32],r0\nCMPI.W #2,r0\nBEQ compiler_ds_ok\nCMPI.W #3,r0\nBNE invalid_candidate\ncompiler_ds_ok:')
    assert kernel.count('CMPI.W #$4000,r0')==2 # Current PCB test plus candidate PC bound.
    symbols=image_symbols(kernel,assemble(kernel,0x8000),0x8000)
    original=(ROOT/'examples/kernel_console.asm').read_text();old=image_symbols(original,assemble(original,0x8000),0x8000)
    assert all(symbols[name]==old[name] for name in ('irq','swi','copy_fault','copy_error','idle','idle_resume'))
    helper_boot=boot.replace('SWI #0\nHALT','MOV.W #11,r0\nPUSH r0\nMOV.W #1000,r0\nPUSH r0\nCALL $B000\nADJSP #4\nMOV.W r0,[$2F00]\nSWI #0\nHALT')
    assert helper_boot!=boot
    image=lambda text,origin:list(b''.join(b for _,b,_ in assemble(text,origin)))
    lines=['// Generated by the production compiler/assembler; do not edit.','#pragma once','#include <cstdint>','#include <string>','#include <vector>','namespace compiler_images {',
           'struct Instruction { unsigned pc,bytes,kind; bool bank_move,address_alu; std::string family; int displacement,addressing,branch; };',
           'struct Check { unsigned offset; std::vector<uint8_t> bytes; };',
           'struct Program { std::string name,variant,input,output; unsigned result,guard,kernel_result; bool preempt,preempt_ss,unchanged; std::vector<uint8_t> code,data,helper; std::vector<Instruction> instructions,helper_instructions; std::vector<Check> memory; };']
    lines.append(f'inline constexpr unsigned finished_pc = {symbols["finished"]+1};')
    vector=lambda data:'{'+','.join(map(str,data))+'}'
    for name,text,origin in [('boot',boot,0x100),('helper_boot',helper_boot,0x100),('kernel',kernel,0x8000)]:lines.append(f'inline const std::vector<uint8_t> {name} = {vector(image(text,origin))};')
    def insns(rows):
        return '{'+','.join('{'+f'{r["pc"]},{r["bytes"]},{KINDS[r["kind"]]},{str(r["bank_move"]).lower()},{str(r["address_alu"]).lower()},'+json.dumps(r['family'])+f',{r.get("displacement",0)},{ {"sp":1,"b1":2}.get(r.get("addressing"),0)},{r.get("branch_distance",100000)}'+'}' for r in rows)+'}'
    lines.append('inline const std::vector<Program> programs = {')
    for a in artifacts:
        memory='{'+','.join('{'+offset+','+vector(data)+'}' for offset,data in a.get('memory',{}).items())+'}'
        helper=a.get('helper_artifact',{});lines.append('{'+','.join([json.dumps(a['name']),json.dumps(a['variant']),json.dumps(a.get('input','')),json.dumps(a.get('output','')),str(a['result']),str(a.get('guard',0)),str(a.get('kernel_result',0)),str(a.get('preempt',False)).lower(),str(a.get('preempt_ss',False)).lower(),str(a.get('unchanged_data',False)).lower(),vector(a['code']),vector(a['data']),vector(helper.get('code',[])),insns(a['instructions']),insns(helper.get('instructions',[])),memory])+'},')
        a['binary_sha256']=digest(bytes(a['code']));a['assembly_sha256']=digest(a['assembly'].encode());a['data_sha256']=digest(bytes(a['data']))
        (out.parent/(a['name']+'.asm')).write_text(a['assembly'])
    lines+=['};','}'];out.write_text('\n'.join(lines)+'\n')
    paths=[ROOT/'tools/smallc.py',ROOT/'tools/isa.py',ROOT/'tools/encoding.py',ROOT/'tools/generate_compiler_fixtures.py',ROOT/'tools/generate_kernel_fixtures.py',ROOT/'src/cpu.cpp',ROOT/'src/cpu.hpp',ROOT/'src/protected.cpp',ROOT/'src/replay.cpp',ROOT/'tests/compiler_conformance.cpp',ROOT/'tests/test_compiler.py',ROOT/'examples/console_guest.hpp',ROOT/'CMakeLists.txt',ROOT/'tools/measure_workloads.py',ROOT/'tools/evaluate_pointer_arithmetic.py',ROOT/'tests/test_pointer_evaluation.py',directory/'corpus.json',*sorted((ROOT/'examples').glob('kernel_*.asm')),*sorted(directory.glob('*.c')),*sorted(directory.glob('*.asm'))]
    payload=payload_text()
    manifest={'compiler':'SmallC 0.1.0','flags':['--baseline'],'mode':'working','profile':'console-v1','git_head':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'working_tree_dirty':bool(subprocess.check_output(['git','status','--porcelain'],cwd=ROOT,text=True).strip()),'encoding_sha256':digest(payload.encode()),'files':{str(p.relative_to(ROOT)):digest(p.read_bytes()) for p in paths if p.exists()},'boot_sha256':digest(bytes(image(boot,0x100))),'kernel_sha256':digest(bytes(image(kernel,0x8000))),'artifacts':artifacts}
    manifest_text=json.dumps(manifest,indent=2)+'\n'
    out.with_suffix('.json').write_text(manifest_text)
    with out.open('a') as header:header.write('namespace compiler_images { inline constexpr const char* manifest_sha256 = '+json.dumps(digest(manifest_text.encode()))+'; }\n')

if __name__=='__main__':generate(sys.argv[1])
